import {
  Bell,
  CircleAlert,
  CircleCheck,
  Info,
  TriangleAlert,
  X,
  type LucideIcon,
} from 'lucide-react'
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'

import { Portal } from '~/components/primitives/portal'
import { cx } from '~/lib/cx'
import { ToasterContext, type Toast, type ToastType } from './sonner-context'
import styles from './sonner.module.scss'

export type ToasterPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'
  | 'top-center'
  | 'bottom-center'

const POSITION: Record<ToasterPosition, string> = {
  'top-left': styles.topLeft,
  'top-right': styles.topRight,
  'top-center': styles.topCenter,
  'bottom-left': styles.bottomLeft,
  'bottom-right': styles.bottomRight,
  'bottom-center': styles.bottomCenter,
}

const TYPE: Record<ToastType, string> = {
  default: styles.default,
  success: styles.success,
  error: styles.error,
  warning: styles.warning,
  info: styles.info,
}

const TYPE_ICON: Record<ToastType, LucideIcon> = {
  default: Bell,
  success: CircleCheck,
  error: CircleAlert,
  warning: TriangleAlert,
  info: Info,
}

export function Toaster({
  position = 'bottom-right',
  children,
}: {
  position?: ToasterPosition
  children?: ReactNode
}) {
  const [toasts, setToasts] = useState<Toast[]>([])
  const timers = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())

  const dismiss = useCallback((id: string) => {
    const timer = timers.current.get(id)
    if (timer) {
      clearTimeout(timer)
      timers.current.delete(id)
    }
    setToasts((prev) => prev.filter((t) => t.id !== id))
  }, [])

  const toast = useCallback(
    (t: Omit<Toast, 'id'>) => {
      const id = Math.random().toString(36).slice(2, 9)
      const duration = t.duration ?? 4000
      const toastItem: Toast = { ...t, id, duration }

      setToasts((prev) => [...prev, toastItem])

      if (duration > 0) {
        const timer = setTimeout(() => dismiss(id), duration)
        timers.current.set(id, timer)
      }
      return id
    },
    [dismiss],
  )

  useEffect(() => {
    const timersMap = timers.current
    return () => {
      timersMap.forEach((timer) => clearTimeout(timer))
      timersMap.clear()
    }
  }, [])

  const value = useMemo(() => ({ toast, dismiss }), [toast, dismiss])

  return (
    <ToasterContext.Provider value={value}>
      {children}
      <Portal>
        <div className={cx(styles.viewport, POSITION[position])}>
          {toasts.map((t, index) => {
            const type = t.type ?? 'default'
            const Icon = TYPE_ICON[type]

            return (
              <div
                key={t.id}
                className={cx(styles.toast, TYPE[type])}
                role={type === 'error' ? 'alert' : 'status'}
                aria-live={type === 'error' ? 'assertive' : 'polite'}
                aria-atomic="true"
                style={{ animationDelay: `${index * 40}ms` }}
              >
                <span className={styles.typeIcon}>
                  <Icon aria-hidden />
                </span>
                <div className={styles.copy}>
                  {t.title ? <p className={styles.title}>{t.title}</p> : null}
                  {t.description ? (
                    <p className={styles.description}>{t.description}</p>
                  ) : null}
                </div>
                {t.action ? (
                  <button
                    type="button"
                    className={styles.action}
                    onClick={() => {
                      t.action?.onClick()
                      dismiss(t.id)
                    }}
                  >
                    {t.action.label}
                  </button>
                ) : null}
                <button
                  type="button"
                  className={styles.dismiss}
                  onClick={() => dismiss(t.id)}
                  aria-label="Dismiss notification"
                >
                  <X aria-hidden />
                </button>
              </div>
            )
          })}
        </div>
      </Portal>
    </ToasterContext.Provider>
  )
}

export { Toaster as Sonner }
export { toast, useToast } from './sonner-context'
export type { Toast, ToastType, ToasterContextValue } from './sonner-context'

@use 'styles' as vz;

.viewport {
  position: fixed;
  z-index: vz.z('toast');
  display: flex;
  width: 23rem;
  max-width: calc(100vw - #{vz.space(6)});
  flex-direction: column;
  gap: vz.space(2.5);
  padding: 0;
  pointer-events: none;
}

.top-left {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  left: vz.space(4);
}

.top-right {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  right: vz.space(4);
}

.top-center {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  left: 50%;
  translate: -50% 0;
}

.bottom-left {
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
  left: vz.space(4);
}

.bottom-right {
  right: vz.space(4);
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
}

.bottom-center {
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
  left: 50%;
  translate: -50% 0;
}

.toast {
  --toast-accent: #{vz.color('muted-foreground')};
  --toast-tint: #{vz.color('muted')};

  display: flex;
  align-items: flex-start;
  gap: vz.space(2.5);
  width: 100%;
  padding: vz.space(3);
  border: 1px solid vz.color('border', 0.72);
  border-radius: vz.radius('lg');
  background: vz.color('popover', 0.86);
  color: vz.color('popover-foreground');
  box-shadow:
    vz.elevation(3),
    0 1px 0 hsl(0deg 0% 100% / 60%) inset;
  backdrop-filter: blur(20px) saturate(180%);
  pointer-events: auto;
  animation: vz-toast-in 260ms vz.ease('spring') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

:global(.dark) .toast {
  box-shadow:
    0 16px 40px hsl(0deg 0% 0% / 45%),
    0 1px 0 hsl(210deg 40% 98% / 8%) inset;
}

.default {
  --toast-accent: #{vz.color('foreground')};
  --toast-tint: #{vz.color('muted')};
}

.success {
  --toast-accent: #{vz.color('success')};
  --toast-tint: #{vz.color('success', 0.12)};
}

.error {
  --toast-accent: #{vz.color('destructive')};
  --toast-tint: #{vz.color('destructive', 0.1)};
}

.warning {
  --toast-accent: #{vz.color('warning')};
  --toast-tint: #{vz.color('warning', 0.14)};
}

.info {
  --toast-accent: #{vz.color('info')};
  --toast-tint: #{vz.color('info', 0.12)};
}

.type-icon {
  display: inline-flex;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
  border-radius: vz.radius('full');
  background: var(--toast-tint);
  color: var(--toast-accent);

  svg {
    @include vz.icon(3.5);
  }
}

.copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.45;
}

.dismiss {
  display: inline-flex;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  align-items: center;
  justify-content: center;
  margin: -2px -2px 0 0;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('foreground', 0.06);
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(3);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.action {
  display: inline-flex;
  flex: none;
  align-items: center;
  align-self: center;
  height: 1.75rem;
  padding-inline: vz.space(2.5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('sm');
  background: vz.color('accent');
  color: vz.color('accent-foreground');
  font-size: 0.6875rem;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    border-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted');
    border-color: vz.color('foreground', 0.2);
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

@include vz.up('sm') {
  .viewport {
    width: 24rem;
  }
}

@include vz.down('sm') {
  .viewport {
    right: vz.space(3);
    left: vz.space(3);
    width: auto;
    max-width: none;
  }

  .top-center,
  .bottom-center {
    translate: 0 0;
  }
}

@keyframes vz-toast-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

import { createContext, useContext } from 'react'

export type ToastType = 'default' | 'success' | 'error' | 'warning' | 'info'

export interface Toast {
  id: string
  title?: string
  description?: string
  type?: ToastType
  duration?: number
  action?: { label: string; onClick: () => void }
}

export interface ToasterContextValue {
  toast: (toast: Omit<Toast, 'id'>) => string
  dismiss: (id: string) => void
}

export const ToasterContext = createContext<ToasterContextValue | null>(null)

export function useToast() {
  const ctx = useContext(ToasterContext)
  if (!ctx) throw new Error('useToast must be used within <Toaster>')
  return ctx
}

/**
 * Imperative fallback for callers outside a React tree. Prefer `useToast()`
 * so the toast is rendered by the nearest <Toaster>.
 */
export const toast = (_t: Omit<Toast, 'id'>) => {
  console.warn('Use useToast() hook from Toaster context')
  return ''
}
